CREATE FUNCTION cm_deny_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION '% is append-only', TG_TABLE_NAME; END $$;
CREATE TRIGGER trg_cm_question_revision_event_append_only BEFORE UPDATE OR DELETE ON cm_question_revision_event FOR EACH ROW EXECUTE FUNCTION cm_deny_mutation();
