DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='certmuse_app') THEN CREATE ROLE certmuse_app NOLOGIN; END IF; END $$;
GRANT USAGE ON SCHEMA public TO certmuse_app;
DO $$
DECLARE r record;
BEGIN
  FOR r IN SELECT tablename FROM pg_tables WHERE schemaname='public' AND tablename LIKE 'cm\_%' ESCAPE '\' LOOP
    EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE %I TO certmuse_app', r.tablename);
  END LOOP;
END $$;
REVOKE UPDATE, DELETE ON cm_question_revision_event FROM certmuse_app;
REVOKE UPDATE, DELETE ON cm_user_goal_change FROM certmuse_app;
REVOKE UPDATE, DELETE ON cm_hint_usage FROM certmuse_app;
REVOKE UPDATE, DELETE ON cm_profile_change FROM certmuse_app;
REVOKE UPDATE, DELETE ON cm_learning_evidence_event FROM certmuse_app;
REVOKE UPDATE, DELETE ON cm_profile_checkpoint FROM certmuse_app;
REVOKE UPDATE, DELETE ON cm_learning_event FROM certmuse_app;
REVOKE UPDATE, DELETE ON cm_business_audit_log FROM certmuse_app;
REVOKE UPDATE, DELETE ON cm_rule_hit FROM certmuse_app;
REVOKE UPDATE, DELETE ON cm_exception_action FROM certmuse_app;
