VALUES (900000000000000031,'PROFILE_V8','published','profile_rule/1.0','{"aggregation":{"exclude_expired":true,"exclude_unassessed":true,"importance_weights":{"core":3,"normal":2,"supplement":1}},"behavior":{},"confidence":{},"evidence":{"easy":{"correct":70,"wrong":10},"hard":{"correct":95,"wrong":40},"medium":{"correct":85,"wrong":25}},"freshness":{"boundaries_days":[30,60,90],"regression_correct_coefficients":{"days_31_60":1.1,"days_61_90":1.15,"default":1.0,"over_90_days":1.15}},"hint_and_time":{"correct_max":1.21,"grace_ratio":1.2,"hint_levels":{},"standard_seconds":{"easy":20,"hard":60,"medium":40},"time_bands":{"fast":{"correct":1.05,"wrong":1.1},"fluent":{"correct":1.03,"wrong":1.0},"grace":{"correct":0.9,"wrong":1.05},"normal":{"correct":1.0,"wrong":1.0},"timeout":{"wrong":1.1}},"wrong_max":1.6},"readiness":{},"schema_version":"1.0"}'::jsonb,'235c349da5fc6597cc98ed524acd079071562170f497b4136fb9333f72e8c26e',now())
ON CONFLICT (version_code) DO UPDATE SET config_data=EXCLUDED.config_data, content_hash=EXCLUDED.content_hash, update_time=now();
DO $$
DECLARE table_count integer; id_pk_count integer;
BEGIN
 SELECT count(*) INTO table_count FROM information_schema.tables WHERE table_schema='public' AND table_name LIKE 'cm\_%' ESCAPE '\';
 IF table_count <> 66 THEN RAISE EXCEPTION 'expected 66 cm tables, got %',table_count; END IF;
 SELECT count(*) INTO id_pk_count FROM information_schema.table_constraints tc JOIN information_schema.key_column_usage kcu ON kcu.constraint_name=tc.constraint_name AND kcu.table_schema=tc.table_schema WHERE tc.table_schema='public' AND tc.constraint_type='PRIMARY KEY' AND tc.table_name LIKE 'cm\_%' ESCAPE '\' AND kcu.column_name='id';
 IF id_pk_count <> 65 THEN RAISE EXCEPTION 'expected 65 id primary keys, got %',id_pk_count; END IF;
 IF NOT EXISTS (SELECT 1 FROM information_schema.table_constraints WHERE table_schema='public' AND table_name='cm_collection_current' AND constraint_type='PRIMARY KEY') THEN RAISE EXCEPTION 'missing collection current natural primary key'; END IF;
 IF NOT EXISTS (SELECT 1 FROM cm_profile_rule_version WHERE version_code='PROFILE_V8') THEN RAISE EXCEPTION 'missing PROFILE_V8 seed'; END IF;
END $$;
COMMIT;
